let map, markersById = {}, activeCase = null;

function initMap() {
  map = L.map('map', {
    center: [15, 20], zoom: 2, minZoom: 1, maxZoom: 10,
    zoomControl: true, attributionControl: true
  });

  L.tileLayer('https://{s}.basemaps.cartocdn.com/light_nolabels/{z}/{x}/{y}{r}.png?key=cb1_2ekc_1_9785a96b9180d173cb4d6a69', {
    attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors © <a href="https://carto.com/">CARTO</a>',
    subdomains: 'abcd', maxZoom: 19
  }).addTo(map);

  const GEO_LABELS = [
    { text: 'NORTH AMERICA',  lat: 48,   lng: -100 },
    { text: 'SOUTH AMERICA',  lat: -15,  lng: -58  },
    { text: 'EUROPE',         lat: 54,   lng: 18   },
    { text: 'AFRICA',         lat: 3,    lng: 22   },
    { text: 'ASIA',           lat: 45,   lng: 90   },
    { text: 'AUSTRALIA',      lat: -26,  lng: 134  },
    { text: 'PACIFIC OCEAN',  lat: 5,    lng: -155 },
    { text: 'ATLANTIC OCEAN', lat: 10,   lng: -30  },
    { text: 'INDIAN OCEAN',   lat: -22,  lng: 75   },
    { text: 'ARCTIC OCEAN',   lat: 82,   lng: 0    },
  ];

  GEO_LABELS.forEach(({ text, lat, lng }) => {
    L.marker([lat, lng], {
      icon: L.divIcon({
        className: '',
        html: `<span class="map-geo-label">${text}</span>`,
        iconSize: null, iconAnchor: [0, 0]
      }),
      interactive: false, zIndexOffset: -1000
    }).addTo(map);
  });

  Object.entries(CASES).forEach(([id, data]) => {
    const color = COLOR[data.region];
    const numId = parseInt(id);
    const dollSrc = DOLL_ICONS[data.region];

    const svgIcon = L.divIcon({
      className: '',
      html: `<img src="${dollSrc}" style="width:30px;height:50px;object-fit:contain;filter:drop-shadow(0 2px 6px rgba(0,0,0,0.45));transition:transform 0.15s;" onmouseover="this.style.transform='scale(1.15)'" onmouseout="this.style.transform='scale(1)'">`,
      iconSize: [30, 50], iconAnchor: [15, 50], popupAnchor: [0, -52]
    });

    const marker = L.marker([data.lat, data.lng], { icon: svgIcon });
    const popupHtml = `
      <div class="popup-inner">
        <div class="popup-region" style="color:${color}">${data.regionLabel} · CASE ${data.num}</div>
        <div class="popup-title">${data.title}</div>
        <button class="popup-btn" onclick="selectCase(${numId});closePopup()">VIEW FULL CASE STUDY ▶</button>
      </div>`;

    marker.bindPopup(popupHtml, { maxWidth: 280, closeButton: true });
    marker.on('click', () => marker.openPopup());
    marker.addTo(map);
    markersById[numId] = marker;
  });
}

function closePopup() { map.closePopup(); }

// ─── FOOTNOTE RENDERER ───────────────────────────────────────────────────────
function linkifyBodyRefs(html, prefix) {
  return html.replace(/\[(\d+)\]/g, (match, num) =>
    `<sup><a class="fn-ref" id="${prefix}-ref-${num}" data-target="${prefix}-fn-${num}" href="#">${match}</a></sup>`
  );
}

function renderFootnotes(footnotes, listId, containerEl, prefix) {
  if (!footnotes || footnotes.length === 0) {
    containerEl.style.display = 'none';
    return;
  }
  containerEl.style.display = 'block';
  document.getElementById(listId).innerHTML = footnotes.map(f =>
    `<div class="footnote-item" id="${prefix}-fn-${f.num}">
      <a class="fn-back" data-target="${prefix}-ref-${f.num}" href="#" title="Back to reference">↑</a>
      <span class="footnote-num">[${f.num}]</span>
      <span class="footnote-text">${f.text}</span>
    </div>`
  ).join('');
}

document.addEventListener('click', function(e) {
  const link = e.target.closest('.fn-ref, .fn-back');
  if (!link) return;
  e.preventDefault();
  const target = document.getElementById(link.dataset.target);
  if (!target) return;
  const block = link.classList.contains('fn-back') ? 'center' : 'start';
  target.scrollIntoView({ behavior: 'smooth', block });
});

// ─── RESIZABLE DETAIL PANEL ──────────────────────────────────────────────────
(function () {
  const handle = document.getElementById('detailResizeHandle');
  const panel  = document.getElementById('detailPanel');
  const HEADER_H = 61; // px — matches the fixed header height
  const MIN_H = 80;

  handle.addEventListener('mousedown', function (e) {
    const startY = e.clientY;
    const startH = panel.offsetHeight;
    handle.classList.add('is-dragging');
    document.body.style.cursor    = 'ns-resize';
    document.body.style.userSelect = 'none';

    function onMove(e) {
      const maxH = window.innerHeight - HEADER_H - 120; // keep ≥120px for map
      const newH = Math.min(Math.max(startH + (startY - e.clientY), MIN_H), maxH);
      panel.style.height = newH + 'px';
    }

    function onUp() {
      handle.classList.remove('is-dragging');
      document.body.style.cursor     = '';
      document.body.style.userSelect = '';
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup',   onUp);
    }

    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup',   onUp);
    e.preventDefault();
  });
}());
function convertTakeawayLists(container) {
  container.querySelectorAll('.takeaway-list').forEach(list => {
    const table = document.createElement('table');
    table.className = 'implication-table';
    list.querySelectorAll('.takeaway').forEach(item => {
      const strong = item.querySelector('strong');
      const titleHtml = strong ? strong.outerHTML : '';
      let descHtml = '';
      item.childNodes.forEach(node => {
        if (node !== strong) descHtml += node.nodeType === 3 ? node.textContent : node.outerHTML;
      });
      const tr = document.createElement('tr');
      tr.innerHTML = `<td class="implication-bullet">▸</td><td class="implication-title">${titleHtml}</td><td class="implication-desc">${descHtml.trim()}</td>`;
      table.appendChild(tr);
    });
    list.replaceWith(table);
  });
}

function renderImageMarkup(images) {
  if (!images || !images.length) return '';
  return `
    <div class="detail-image-grid">
      ${images.map(img => `
        <figure class="detail-image-card">
          <img src="${encodeURI(img.src)}" alt="${img.alt || ''}">
        </figure>
      `).join('')}
    </div>`;
}
// ─── SELECT CASE ─────────────────────────────────────────────────────────────
function selectCase(id) {
  const data = CASES[id];
  if (!data) return;
  activeCase = id;
  const color = COLOR[data.region];

  document.querySelectorAll('.case-item, .synthesis-item').forEach(el => el.classList.toggle('active', el.dataset.id == id));
  if (markersById[id]) map.flyTo([data.lat, data.lng], 5, { duration: 1.2 });

  const dMeta = document.getElementById('d-meta');
  const dTitle = document.getElementById('d-title');
  dMeta.textContent = `// ${data.regionLabel} · CASE ${data.num}`;
  dMeta.style.color = color;
  dTitle.textContent = data.title;
  dTitle.style.borderLeft = `3px solid ${color}`;
  dTitle.style.paddingLeft = '10px';
  document.getElementById('d-tags').innerHTML = data.tags.map(t => `<span class="tag">${t}</span>`).join('');
  document.getElementById('d-body').innerHTML = linkifyBodyRefs(data.body + renderImageMarkup(data.images), 'd');
  convertTakeawayLists(document.getElementById('d-body'));
  renderFootnotes(data.footnotes, 'd-footnote-list', document.getElementById('d-footnotes'), 'd');
  document.getElementById('detailEmpty').style.display = 'none';
  document.getElementById('detailContent').classList.add('active');

  if (window.innerWidth <= 768) {
    const mMeta = document.getElementById('m-meta');
    const mTitle = document.getElementById('m-title');
    mMeta.textContent = `// ${data.regionLabel} · CASE ${data.num}`;
    mMeta.style.color = color;
    mTitle.textContent = data.title;
    mTitle.style.borderLeft = `3px solid ${color}`;
    mTitle.style.paddingLeft = '10px';
    document.getElementById('m-tags').innerHTML = data.tags.map(t => `<span class="tag">${t}</span>`).join('');
    document.getElementById('m-body').innerHTML = linkifyBodyRefs(data.body + renderImageMarkup(data.images), 'm');
    convertTakeawayLists(document.getElementById('m-body'));
    renderFootnotes(data.footnotes, 'm-footnote-list', document.getElementById('m-footnotes'), 'm');
    document.getElementById('mobileModal').classList.add('active');
  }
}

function closeDetail() {
  document.getElementById('detailEmpty').style.display = 'flex';
  document.getElementById('detailContent').classList.remove('active');
  document.querySelectorAll('.case-item, .synthesis-item').forEach(el => el.classList.remove('active'));
  activeCase = null;
}

function closeMobileModal() { document.getElementById('mobileModal').classList.remove('active'); }

document.getElementById('mobileModal').addEventListener('click', function(e) {
  if (e.target === this) closeMobileModal();
});

// ─── SELECT SYNTHESIS ────────────────────────────────────────────────────────
function selectSynthesis(id) {
  const data = SYNTHESES[id];
  if (!data) return;
  activeCase = null;
  const color = COLOR[data.region];

  document.querySelectorAll('.case-item, .synthesis-item').forEach(el => el.classList.remove('active'));
  const synthEl = document.querySelector(`.synthesis-item[data-synth-id="${id}"]`);
  if (synthEl) synthEl.classList.add('active');

  const dMeta = document.getElementById('d-meta');
  const dTitle = document.getElementById('d-title');
  dMeta.textContent = `// ${data.regionLabel} · CROSS-CASE SYNTHESIS`;
  dMeta.style.color = color;
  dTitle.textContent = data.title;
  dTitle.style.borderLeft = `3px solid ${color}`;
  dTitle.style.paddingLeft = '10px';
  document.getElementById('d-tags').innerHTML = data.tags.map(t => `<span class="tag">${t}</span>`).join('');
  document.getElementById('d-body').innerHTML = linkifyBodyRefs(data.body + renderImageMarkup(data.images), 'd');
  convertTakeawayLists(document.getElementById('d-body'));
  renderFootnotes(data.footnotes, 'd-footnote-list', document.getElementById('d-footnotes'), 'd');
  document.getElementById('detailEmpty').style.display = 'none';
  document.getElementById('detailContent').classList.add('active');

  if (window.innerWidth <= 768) {
    const mMeta = document.getElementById('m-meta');
    const mTitle = document.getElementById('m-title');
    mMeta.textContent = `// ${data.regionLabel} · CROSS-CASE SYNTHESIS`;
    mMeta.style.color = color;
    mTitle.textContent = data.title;
    mTitle.style.borderLeft = `3px solid ${color}`;
    mTitle.style.paddingLeft = '10px';
    document.getElementById('m-tags').innerHTML = data.tags.map(t => `<span class="tag">${t}</span>`).join('');
    document.getElementById('m-body').innerHTML = linkifyBodyRefs(data.body + renderImageMarkup(data.images), 'm');
    convertTakeawayLists(document.getElementById('m-body'));
    renderFootnotes(data.footnotes, 'm-footnote-list', document.getElementById('m-footnotes'), 'm');
    document.getElementById('mobileModal').classList.add('active');
  }
}

// ─── REGION FILTERS ──────────────────────────────────────────────────────────
document.querySelectorAll('.filter-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const region = btn.dataset.region;
    activeRegionFilter = region;
    document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');

    document.querySelectorAll('.case-item').forEach(item => {
      item.classList.toggle('hidden', region !== 'all' && item.dataset.region !== region);
    });

    document.querySelectorAll('.synthesis-item').forEach(item => {
      item.classList.toggle('hidden', region !== 'all' && item.dataset.region !== region);
    });

    Object.entries(markersById).forEach(([id, marker]) => {
      const show = region === 'all' || CASES[id].region === region;
      const el = marker.getElement();
      if (el) { el.style.opacity = show ? '1' : '0.15'; el.style.pointerEvents = show ? 'auto' : 'none'; }
    });

    const visibleCases = Object.values(CASES).filter(c => region === 'all' || c.region === region);
    if (visibleCases.length > 0) {
      const bounds = L.latLngBounds(visibleCases.map(c => [c.lat, c.lng]));
      map.flyToBounds(bounds.pad(0.3), { duration: 1.0, maxZoom: 6 });
    }

    if (activeCase && region !== 'all' && CASES[activeCase].region !== region) closeDetail();
    updateRegionOverviewBtn(region);
  });
});

window.addEventListener('DOMContentLoaded', initMap);

// ─── IFRAME AUTO-HEIGHT (for the WordPress embed) ────────────────────────────
// This page is displayed at gpwmdcounterdisinfo.com inside a fixed-height
// iframe. On mobile that produces a nested scrollbar (scroll the page, then
// scroll trapped content inside the iframe box). When embedded, report our
// real content height to the parent window on load/resize/content-change so
// the parent can resize the iframe to match and avoid double scrolling.
// No-ops entirely when the page isn't embedded. See EMBEDDING.md for the
// matching WordPress-side listener snippet.
(function () {
  if (window.self === window.top) return; // not embedded, nothing to do

  const MESSAGE_TYPE = 'matryoshka:resize';
  let lastHeight = 0;

  function reportHeight() {
    const height = Math.max(document.documentElement.scrollHeight, document.body.scrollHeight);
    if (height === lastHeight) return;
    lastHeight = height;
    window.parent.postMessage({ type: MESSAGE_TYPE, height }, '*');
  }

  new ResizeObserver(reportHeight).observe(document.documentElement);
  window.addEventListener('load', reportHeight);
  window.addEventListener('resize', reportHeight);
  reportHeight();
})();
